const ELEMENT_PROP_KEYS = new Set(["theme","highlight","stagger","pause","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  highlight: "It’s in the repo.",
  stagger: 4,
  pause: 26,
  fontFamily: "Young Serif",
  scale: 1,
  delay: 0,
  speed: 1,
};

type OverheardElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof OverheardBase>;

const OverheardInner = forwardRef<
  HTMLDivElement,
  OverheardElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Overheard>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <OverheardBase
          {...(componentProps as unknown as ComponentProps<typeof OverheardBase>)}
        />
      </div>
    </Sequence>
  );
});

